insert into public.reviews (id, product_id, author, city, rating, title, body, date, verified, status) values
  ('r1', 'p01', 'Ayesha K.', 'Lahore', 5, 'Smells like a real garland', 'Not the sweet synthetic rose I was expecting. It smells like fresh gulab and it lasted the whole evening in our lounge.', '2026-10-28', true, 'Approved'),
  ('r2', 'p01', 'Hira S.', 'Islamabad', 5, 'Bought three more', 'Gave one to my mother and she asked where I got it. Packaging was careful and it arrived in two days.', '2026-10-12', true, 'Approved'),
  ('r3', 'p01', 'Bilal R.', 'Karachi', 4, 'Lovely, burns evenly', 'Burned down flat with no tunnelling. I would like a stronger throw in a big room, so I light two.', '2026-09-30', true, 'Approved'),
  ('r4', 'p02', 'Maham T.', 'Faisalabad', 5, 'It really is doodh patti', 'My husband walked in and asked who made chai. Warm and spicy without being heavy.', '2026-11-02', true, 'Approved'),
  ('r5', 'p02', 'Usman A.', 'Lahore', 4, 'Great winter candle', 'The cardamom comes through first. The jar is nice enough to keep afterwards.', '2026-10-19', false, 'Approved'),
  ('r6', 'p04', 'Sana M.', 'Karachi', 5, 'Guests always ask about it', 'Rich but not smoky. I light it half an hour before people arrive and the whole drawing room changes.', '2026-10-05', true, 'Approved'),
  ('r7', 'p03', 'Zainab F.', 'Multan', 5, 'Exactly like motia', 'Reminds me of my nani tying motia in her hair. Soft, clean and not overpowering.', '2026-11-06', true, 'Approved'),
  ('r8', 'p11', 'Fatima N.', 'Rawalpindi', 5, 'Perfect gift', 'Sent it to a friend for her new home. The box is beautiful and the handwritten note was a lovely touch.', '2026-10-22', true, 'Approved'),
  ('r9', 'p13', 'Omar J.', 'Lahore', 5, 'December in a jar', 'The wooden wick crackles a little. With the woodsmoke scent it feels like sitting by a fire.', '2026-11-09', true, 'Approved')
